//! A dependency-free Rust port of the `sortedcontainers` C++ header.
//!
//! The containers keep their elements in ascending order using a two-level
//! list-of-lists layout: a `Vec` of bounded, sorted sublists plus a positional
//! index tree. Inserting or removing therefore shifts only a bounded number of
//! elements, while lookup by rank stays logarithmic.
//!
//! - [`SortedList`] -- a sorted sequence that keeps duplicates.
//! - [`SortedSet`] -- a sorted collection of unique values.
//! - [`SortedDict`] -- a map ordered by key.
//!
//! [`cstdlib`] holds the C `atoi` / `strtol` semantics the original program's
//! command-line parsing relied on.
//!
//! Only the standard library is used.

// The library exposes a full container API; a given binary uses part of it.
// The re-exports below are public API of the `lib` target, but appear unused
// when this file is pulled into a binary as a module.
// EXPERIMENT: crate-root allow(dead_code, unused_imports) removed here.

// The `#[path]` attributes are relative to this file's own directory, so the
// modules resolve identically whether `lib.rs` is compiled as the crate root
// (`cargo build`) or pulled in as a module (`rustc test6.rs`).
#[path = "cstdlib.rs"]
pub mod cstdlib;
#[path = "sorted_dict.rs"]
pub mod sorted_dict;
#[path = "sorted_list.rs"]
pub mod sorted_list;
#[path = "sorted_set.rs"]
pub mod sorted_set;

pub use cstdlib::{c_atoi, c_strtol};
pub use sorted_dict::SortedDict;
pub use sorted_list::{SortedList, DEFAULT_LOAD_FACTOR};
pub use sorted_set::SortedSet;
